// MARK: - Tests

@Suite("TranscriptionEngine unloadModel")
struct TranscriptionEngineUnloadTests {

    // AC 1: TranscriptionEngine protocol declares `func unloadModel() async`
    // Verified by compile-time existential assignment. If the protocol lacks
    // `unloadModel()` this function does not compile → RED.
    @Test
    func `protocol exposes unloadModel via existential`() async {
        let engine: any TranscriptionEngine = StubUnloadEngine()
        // Calling through an existential verifies the method is part of the protocol
        await engine.unloadModel()
        // The call must not crash; we simply verify the existential dispatch works.
        // The value we assert is that the method is callable (compile-time AC).
        // Additional behavioural ACs are tested below.
        #expect(Bool(true))  // compilation reaching here is the assertion
    }

    // AC 2: Default extension provides a no-op so existing conformers compile
    // StubUnloadEngine does NOT override unloadModel(), so it must compile
    // only if the default extension exists. If the default is missing the
    // struct fails to conform → compile error → RED.
    @Test
    func `default no-op unloadModel does not mutate engine state`() async throws {
        let engine = StubUnloadEngine()
        try await engine.loadModel(ModelID("stub-model"))
        // Call the default no-op — engine should still report ready
        await engine.unloadModel()
        let ready = await engine.isReady()
        #expect(ready == true)
        let loaded = await engine.loadedModel
        #expect(loaded == ModelID("stub-model"))
    }

    // AC 3 & 4: unloadModelCalled is set to true and count increments
    // These tests call `unloadModel()` on a tracking engine and assert
    // the flag and counter have correct values.
    @Test
    func `unloadModel sets unloadModelCalled to true`() async {
        let engine = TrackingUnloadEngine()
        let calledBefore = await engine.unloadModelCalled
        #expect(calledBefore == false)
        await engine.unloadModel()
        let calledAfter = await engine.unloadModelCalled
        #expect(calledAfter == true)
    }

    @Test
    func `unloadModel increments unloadModelCallCount on each invocation`() async {
        let engine = TrackingUnloadEngine()
        let countBefore = await engine.unloadModelCallCount
        #expect(countBefore == 0)
        await engine.unloadModel()
        let countAfterOne = await engine.unloadModelCallCount
        #expect(countAfterOne == 1)
        await engine.unloadModel()
        let countAfterTwo = await engine.unloadModelCallCount
        #expect(countAfterTwo == 2)
    }

    // AC 3 extra: unloadModelCalled stays true across multiple calls
    @Test
    func `unloadModelCalled remains true after multiple unload calls`() async {
        let engine = TrackingUnloadEngine()
        await engine.unloadModel()
        await engine.unloadModel()
        let called = await engine.unloadModelCalled
        #expect(called == true)
    }

    // AC 4 extra: count is exactly zero before any call
    @Test
    func `unloadModelCallCount starts at zero`() async {
        let engine = TrackingUnloadEngine()
        let count = await engine.unloadModelCallCount
        #expect(count == 0)
    }
}

