import Foundation

/// Capability protocol for writing and reading transcription data.
///
/// Used by the transcription pipeline to persist results and by the search
/// surface to query stored transcripts. The production conformer satisfies
public protocol TranscriptRepository: Sendable {
    /// Persists or replaces the transcript for a recording.
    ///
    /// Semantics are upsert: if a transcript already exists for `id` it is
    /// overwritten; no prior content is preserved.
    ///
    /// - Parameters:
    ///   - id: The stable identifier of the recording to update.
    ///   - transcript: The transcription result to store.
    /// - Throws: `StorageError` if the write fails (e.g. I/O error, schema
    ///   mismatch, or unknown recording `id`).
    func updateTranscript(id: RecordingID, transcript: TranscriptionResult) async throws

    /// Returns summaries of recordings whose transcript text contains `query`.
    ///
    /// - Parameter query: A substring to match against stored transcript text.
    ///   Case sensitivity is backend-defined; the production backend uses
    ///   case-insensitive full-text search.
